def admit(active, waiting, budget, slots):
    # Reject up front if any waiting reservation exceeds the total budget,
    # even if the FIFO scan would stop before reaching it.
    for value in waiting:
        if value > budget:
            raise ValueError(
                "reservation %d exceeds total budget %d" % (value, budget)
            )

    admitted = []
    used = sum(active)
    for value in waiting:
        fits_budget = used + value <= budget
        fits_slots = len(active) + len(admitted) + 1 <= slots
        if fits_budget and fits_slots:
            admitted.append(value)
            used += value
        else:
            # Stop at the first waiting reservation that does not fit;
            # never skip it or any later one.
            break

    # Slice by index so duplicate values are handled correctly.
    return admitted, waiting[len(admitted):]

def endpoint(base_url, path):
    base = base_url.rstrip('/')
    # Drop an existing /v1 version segment (but not prefixes like /v10)
    if base.endswith('/v1'):
        base = base[:-3].rstrip('/')
    elif base == 'v1':
        base = ''
    return base + '/v1/' + path.lstrip('/')

